package org.apache.commons.cli;

import java.io.*;
import java.io.PrintWriter;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.Iterator;
import java.util.List;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class HelpFormatter_findWrapPos_TriageGen0Test {

    private HelpFormatter formatter;
    private Method findWrapPosMethod;

    @Before
    public void setUp() throws NoSuchMethodException {
        formatter = new HelpFormatter();
        // Accessing protected method via reflection
        findWrapPosMethod = HelpFormatter.class.getDeclaredMethod("findWrapPos", String.class, int.class, int.class);
        findWrapPosMethod.setAccessible(true);
    }

    private int invokeFindWrapPos(String text, int width, int startPos) throws Exception {
        return (int) findWrapPosMethod.invoke(formatter, text, width, startPos);
    }

    @Test
    public void testFindWrapPos_NewlineBeforeWidth() throws Exception {
        // Scenario: '\n' is found within the width limit
        String text = "Hello\nWorld";
        // startPos=0, width=6. '\n' is at index 5. 5 <= 6 is true.
        assertEquals(6, invokeFindWrapPos(text, 6, 0));
    }

    @Test
    public void testFindWrapPos_TabBeforeWidth() throws Exception {
        // Scenario: '\t' is found within the width limit
        String text = "Hello\tWorld";
        // startPos=0, width=6. '\t' is at index 5. 5 <= 6 is true.
        assertEquals(6, invokeFindWrapPos(text, 6, 0));
    }

    @Test
    public void testFindWrapPos_EndOfStringReached() throws Exception {
        // Scenario: startPos + width is beyond or at text length
        String text = "Hello";
        // startPos=0, width=10. 0 + 10 >= 5.
        assertEquals(-1, invokeFindWrapPos(text, 10, 0));
    }

    @Test
    public void testFindWrapPos_FindLastWhitespaceBeforeWidth() throws Exception {
        // Scenario: No \n or \t within width, but there is a space ' ' before width
        // text: "Hello World" (Indices: H=0, e=1, l=2, l=3, o=4, ' '=5, W=6...)
        String text = "Hello World";
        // startPos=0, width=7. No \n or \t. 
        // pos = 7. text.charAt(7) is 'r'. 
        // Loop backwards from 7 until ' ' at index 5.
        assertEquals(5, invokeFindWrapPos(text, 7, 0));
    }

    @Test
    public void testFindWrapPos_ChopAtWidthNoWhitespaceFound() throws Exception {
        // Scenario: No whitespace found between startPos and width, must chop at next whitespace
        // text: "HelloWorld Next"
        String text = "HelloWorld Next";
        // startPos=0, width=5. 
        // Backwards loop from 5 ('W') finds no ' ', '\n', or '\r'.
        // Second loop: start from 5, move forward until whitespace.
        // Index 10 is ' '.
        assertEquals(10, invokeFindWrapPos(text, 5, 0));
    }

    @Test
    public void testFindWrapPos_ChopAtWidthAtEndOfText() throws Exception {
        // Scenario: No whitespace found and next whitespace is end of string
        String text = "HelloWorld";
        // startPos=0, width=5.
        // Backwards loop finds no space.
        // Forward loop starts at 5, goes to end (index 10).
        // Returns -1 because pos == text.length()
        assertEquals(-1, invokeFindWrapPos(text, 5, 0));
    }

    @Test
    public void testFindWrapPos_CarriageReturnInBackwardsLoop() throws Exception {
        // Scenario: Ensure \r stops the backwards search
        String text = "Hello\rWorld";
        // startPos=0, width=7.
        // pos=7 ('r'). 
        // Backwards loop: 7('r'), 6('l'), 5('d'), 4('r'), 3('\r') -> stops.
        // pos becomes 3. Since pos > startPos (3 > 0), returns 3.
        // Wait, the logic: while (c != ' ' && c != '\n' && c != '\r')
        // At index 5 is '\r'. pos becomes 5. 
        // Let's use a clearer string.
        String text2 = "abc\rdef"; // a=0, b=1, c=2, \r=3, d=4, e=5, f=6
        // width 5, start 0. pos=5 ('e').
        // Backwards: index 5('e'), 4('d'), 3('\r') -> stop.
        // pos is 3. 3 > 0, return 3.
        assertEquals(3, invokeFindWrapPos(text2, 5, 0));
    }

    @Test
    public void testFindWrapPos_NoWhitespaceFoundInForwardLoopAtEnd() throws Exception {
        // Scenario: text.length() is reached in the second loop
        String text = "ABC DEFG";
        // startPos=0, width=2. 
        // Backwards from 2 ('C'): 2('C'), 1('B'), 0('A') -> loop ends (pos >= startPos is false after --pos)
        // pos is 0. pos > startPos is false.
        // Second loop starts at pos=2.
        // text.charAt(2)='C', 3=' ', loop stops.
        // returns 3.
        assertEquals(3, invokeFindWrapPos(text, 2, 0));
    }

    @Test
    public void testFindWrapPos_ExactWidthAtEnd() throws Exception {
        // Scenario: width lands exactly at end of text
        String text = "12345";
        // startPos=0, width=5. 0+5 >= 5. returns -1.
        assertEquals(-1, invokeFindWrapPos(text, 5, 0));
    }

    @Test
    public void testFindWrapPos_WhitespaceAtStartPos() throws Exception {
        // Scenario: startPos is at a space
        String text = " Hello";
        // startPos=0, width=3.
        // pos = 3 ('l').
        // Backwards: 3('l'), 2('l'), 1('e'), 0(' ') -> stop.
        // pos is 0. pos > startPos is false.
        // Second loop: starts at 3. 3('l'), 4('l'), 5('o'), 6(end).
        // returns -1.
        // Actually, let's check index: H=1, e=2, l=3, l=4, o=5. 
        // text.charAt(0) is ' '. 
        // pos=3. charAt(3)='l', 2='e', 1='H', 0=' '. Loop stops. pos=0.
        // pos > startPos (0 > 0) is false.
        // pos = 3. charAt(3)='l', 4='l', 5='o', 6=length.
        // return -1.
        assertEquals(-1, invokeFindWrapPos(" Hello", 3, 0));
    }
}
